begin;
create table if not exists public.vault_folders(id uuid primary key default gen_random_uuid(),name text not null,parent_id uuid references public.vault_folders(id),drive_folder_id text,created_at timestamptz not null default now());
alter table public.documents add column if not exists vault_folder_id uuid references public.vault_folders(id);
alter table public.vault_uploads add column if not exists vault_folder_id uuid references public.vault_folders(id);
create table if not exists public.study_annotations(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.documents(id) on delete cascade,page int not null check(page>0),type text not null,color text not null default '#b4b0a7',geometry jsonb not null default '{}',quote text not null default '',comment text not null default '',tags text[] not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.study_notes(id uuid primary key default gen_random_uuid(),document_id uuid not null unique references public.documents(id) on delete cascade,summary text not null default '');
create table if not exists public.study_cards(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.documents(id) on delete cascade,page int not null default 1,type text not null default 'qa',front text not null,back text not null default '',cloze text not null default '',occlusion jsonb not null default '{}',stability float not null default 2.5,difficulty float not null default 0,due timestamptz not null default now(),reps int not null default 0,lapses int not null default 0,last_review timestamptz);
create table if not exists public.study_reviews(id uuid primary key default gen_random_uuid(),card_id uuid not null references public.study_cards(id) on delete cascade,rating int not null check(rating between 1 and 4),reviewed_at timestamptz not null default now(),interval float not null);
create table if not exists public.study_progress(id uuid primary key default gen_random_uuid(),document_id uuid not null unique references public.documents(id) on delete cascade,last_page int not null default 1,zoom float not null default 1,pages_read int[] not null default '{}',total_pages int not null default 0,last_studied_at timestamptz not null default now());
do $$ declare t text;begin foreach t in array array['vault_folders','study_annotations','study_notes','study_cards','study_reviews','study_progress'] loop execute format('alter table public.%I enable row level security',t);execute format('grant all on public.%I to service_role',t);execute format('create index if not exists %I on public.%I(%I)',t||'_lookup',t,case when t='vault_folders' then 'parent_id' when t='study_reviews' then 'card_id' else 'document_id' end);end loop;end $$;
create index if not exists study_cards_due_idx on public.study_cards(due);
notify pgrst,'reload schema';
commit;
